public static void main(Args _args)
{
    FTDQueryVSSelect queryVsSelect = new FTDQueryVSSelect();

    if (Box::yesNo('Do you want to run the select using the query', DialogButton::Yes) == DialogButton::Yes)
    {
        //queryVsSelect.reuseExistingQuery();
        queryVsSelect.buildQueryFromCode();
    }
    else
    {
        queryVsSelect.selectExample();
    }
}
